select left(stem,90) from questions q join subject_groups g on g.id=q.subject_group_id where g.code='medical-science' and (stem ilike '%sterilization%' or stem ilike '%autoclave%' or stem ilike '%insulin%' or stem ilike '%vitamin C%' or stem ilike '%rickets%' or stem ilike '%red blood cells%' or stem ilike '%haemoglobin%' or stem ilike '%hemoglobin%' or stem ilike '%pancreas%' or stem ilike '%kidney%' or stem ilike '%BCG%' or stem ilike '%mosquito%' or stem ilike '%iodine%' or stem ilike '%heart%');
